const REL_BRANCH={k:"Вожовы",s:"Кольцовы",g:"Смолины",n:"Звягинцевы, Романовы, Ивановы",o:"Однофамильцы"};
const REL_SECT=[["finds","Находки"],["fixes","Исправлено"],["site","На сайте"],["next","Запросы и планы"]];
function renderReleases(box){
  const M=["января","февраля","марта","апреля","мая","июня","июля","августа","сентября","октября","ноября","декабря"];
  const e=s=>String(s).replace(/&/g,"&amp;").replace(/</g,"&lt;");
  const day=d=>{const[y,m,dd]=d.split("-").map(Number);return dd+" "+M[m-1]+" "+y;};
  box.innerHTML=RELEASES.slice().sort((a,b)=>b.date.localeCompare(a.date)).map(r=>{
    let h=`<article class="upd"><h3>${day(r.date)}</h3>`;
    REL_SECT.forEach(([k,t])=>{
      const L=r[k];if(!L||!L.length)return;
      h+=`<h4>${t}</h4>`;
      if(k==="finds"){
        Object.keys(REL_BRANCH).forEach(b=>{const it=L.filter(x=>x[0]===b);if(!it.length)return;
          h+=`<div class="upd-br"><span class="upd-tag ${b}">${REL_BRANCH[b]}</span><ul>${it.map(x=>`<li>${e(x[1])}</li>`).join("")}</ul></div>`;});
      } else h+=`<ul>${L.map(x=>`<li>${e(x)}</li>`).join("")}</ul>`;
    });
    return h+`</article>`;
  }).join("");
}

